   \"title\": \"%command.reloadRuntime%\",\n        \"icon\": \"$(refresh)\"\n      },\n      {\n        \"command\": \"deepseekHarness.setApiKey\",\n        \"title\": \"%command.setApiKey%\"\n      },\n      {\n        \"command\": \"deepseekHarness.clearApiKey\",\n        \"title\": \"%command.clearApiKey%\"\n      },\n      {\n        \"command\": \"deepseekHarness.testSystemNotification\",\n        \"title\": \"%command.testSystemNotification%\"\n      },\n      {\n        \"command\": \"deepseekHarness.showLogs\",\n        \"title\": \"%command.showLogs%\"\n      },\n      {\n        \"command\": \"deepseekHarness.importSession\",\n        \"title\": \"%command.importSession%\",\n        \"icon\": \"$(cloud-download)\"\n      }\n    ],\n    \"viewsContainers\": {\n      \"activitybar\": [\n        {\n          \"id\": \"deepseekHarness\",\n          \"title\": \"DeepSeek Harness for Visual Studio Code\",\n          \"icon\": \"media/deepseek-harness.svg\"\n        }\n      ]\n    },\n    \"views\": {\n      \"deepseekHarness\": [\n        {\n          \"id\": \"deepseekHarness.chatView\",\n          \"name\": \"%view.chat%\",\n          \"type\": \"webview\"\n        }\n      ]\n    },\n    \"menus\": {\n      \"view/title\": [\n        {\n          \"command\": \"deepseekHarness.openChatWindow\",\n          \"when\": \"view == deepseekHarness.chatView\",\n          \"group\": \"navigation@3\"\n        },\n        {\n          \"command\": \"deepseekHarness.reloadRuntime\",\n          \"when\": \"view == deepseekHarness.chatView\",\n          \"group\": \"navigation@1\"\n        },\n        {\n          \"command\": \"deepseekHarness.showLogs\",\n          \"when\": \"view == deepseekHarness.chatView\",\n          \"group\": \"navigation@2\"\n        },\n        {\n          \"command\": \"deepseekHarness.importSession\",\n          \"when\": \"view == deepseekHarness.chatView\",\n          \"group\": \"navigation@4\"\n        }\n      ]\n    },\n    \"keybind