       \"deepseekHarness.agentPreset\": {\n          \"type\": \"string\",\n          \"enum\": [\n            \"standard\",\n            \"ptc\",\n            \"minimal\",\n            \"cordis\"\n          ],\n          \"enumDescriptions\": [\n            \"%config.preset.standard%\",\n            \"%config.preset.code%\",\n            \"%config.preset.minimal%\",\n            \"%config.preset.cordis%\"\n          ],\n          \"default\": \"standard\",\n          \"description\": \"%config.preset%\"\n        },\n        \"deepseekHarness.provider\": {\n          \"type\": \"string\",\n          \"default\": \"deepseek-official\",\n          \"description\": \"%config.provider%\"\n        },\n        \"deepseekHarness.permissionMode\": {\n          \"type\": \"string\",\n          \"enum\": [\n            \"read-only\",\n            \"workspace-write\",\n            \"danger-full-access\"\n          ],\n          \"enumDescriptions\": [\n            \"%config.permission.readOnly%\",\n            \"%config.permission.workspaceWrite%\",\n            \"%config.permission.dangerFullAccess%\"\n          ],\n          \"default\": \"workspace-write\",\n          \"description\": \"%config.permission%\"\n        },\n        \"deepseekHarness.autoAttachSelection\": {\n          \"type\": \"boolean\",\n          \"default\": true,\n          \"markdownDescription\": \"%config.autoAttachSelection%\"\n        },\n        \"deepseekHarness.webSearch\": {\n          \"type\": \"boolean\",\n          \"default\": true,\n          \"markdownDescription\": \"%config.webSearch%\"\n        },\n        \"deepseekHarness.webSearchProvider\": {\n          \"type\": \"string\",\n          \"enum\": [\n            \"messages\",\n            \"search-api\"\n          ],\n          \"enumDescriptions\": [\n            \"%config.webSearchProvider.messages%\",\n            \"%config.webSearchProvider.searchApi%\"\n          ],\n          \"default\": \"messages\",\n          \"markdownDescription\": \"%config.webSearchProvider%\"\n        },\n        \"deepseekHarness.experimentalAutoEffort\": {\n          \"type\": \"boolean\",\n          \"default\": false,\n          \"markdownDescription\": \"%config.experimentalAutoEffort%\"\n        },\n        \"deepseekHarness.worktreeAutoMerge\": {\n          \"type\": \"string\",\n          \"enum\": [\n            \"never\",\n            \"onTurnEnd\"\n          ],\n          \"enumDescriptions\": [\n            \"%config.worktreeAutoMerge.never%\",\n            \"%config.worktreeAutoMerge.onTurnEnd%\"\n          ],\n          \"default\": \"never\",\n          \"description\": \"%config.worktreeAutoMerge%\"\n        },\n        \"deepseekHarness.mcpServers\": {\n          \"type\": \"string\",\n          \"default\": \"[]\",\n          \"scope\": \"application\",\n          \"markdownDescription\": \"%config.mcpServers%\"\n        }\n      }\n    }\n  },\n  \"devDependencies\": {\n    \"@eslint/js\": \"^9.33.0\",\n    \"@types/node\": \"^24.0.0\",\n    \"@types/vscode\": \"1.101.0\",\n    \"@types/ws\": \"^8.18.1\",\n    \"@vscode/vsce\": \"^3.6.0\",\n    \"esbuild\": \"^0.25.9\",\n    \"eslint\": \"^9.33.0\",\n    \"fzstd\": \"0.1.1\",\n    \"happy-dom\": \"20.14.0\",\n    \"typescript\": \"^5.9.2\",\n    \"typescript-eslint\": \"^8.39.1\",\n    \"vitest\": \"^4.0.0\"\n  },\n  \"dependencies\": {\n    \"@deepseek-ai/dsh\": \"0.2.1-rc.3\",\n    \"dompurify\": \"3.4.17\",\n    \"highlight.js\": \"^11.12.0\",\n    \"markdown-it\": \"15.0.3\",\n    \"node\": \"22.22.3\",\n    \"pnpm\": \"11.21.0\",\n    \"undici\": \"^7.29.0\",\n    \"ws\": \"^8.21.3\"\n  },\n  \"allowScripts\": {\n    \"node@22.22.3\": true,\n    \"esbuild@0.25.12\": true,\n    \"node-pty@1.2.0-beta.15\": true,\n    \"koffi@3.3.1\": true,\n    \"keytar@7.9.0\": true,\n    \"protobufjs@7.6.6\": true,\n    \"@deepseek-ai/dsh-subprocess-local@0.2.1-rc.3\": true,\n    \"@vscode/vsce-sign@2.0.9\": true,\n    \"@google/genai@1.52.0\": true\n  },